106	export async function getCorrectedFileContent(
107	  config: Config,
108	  filePath: string,
109	  proposedContent: string,
110	  abortSignal: AbortSignal,
111	): Promise<GetCorrectedFileContentResult> {
112	  let originalContent = '';
113	  let fileExists = false;
114	  let correctedContent = proposedContent;
115	
116	  // Resolve and validate the path against workspace boundaries (or the plans
117	  // directory in plan mode). This surfaces "Path not in workspace" and
118	  // "Failed to resolve path" (circular symbolic link) errors early.
119	  let resolvedPath: string;
120	  try {
121	    resolvedPath = resolveAndValidateToolPath(filePath, config);
122	  } catch (err) {
123	    return {
124	      originalContent,
125	      correctedContent,
126	      fileExists,
127	      error: {
128	        message: getErrorMessage(err),
129	        code: isNodeError(err) ? err.code : undefined,
130	      },
131	    };
132	  }
133	
134	  try {
135	    originalContent = await config
136	      .getFileSystemService()
137	      .readTextFile(resolvedPath);
138	    fileExists = true; // File exists and was read
139	  } catch (err) {
140	    if (isNodeError(err) && err.code === 'ENOENT') {
141	      fileExists = false;
142	      originalContent = '';
143	    } else {
144	      // File exists but could not be read (permissions, etc.)
145	      fileExists = true; // Mark as existing but problematic
146	      originalContent = ''; // Can't use its content
147	      const error = {
148	        message: getErrorMessage(err),
149	        code: isNodeError(err) ? err.code : undefined,
150	      };
151	      // Return early as we can't proceed with content correction meaningfully
152	      return { originalContent, correctedContent, fileExists, error };
153	    }
154	  }
155	
156	  // In plan mode we resolve against the plans directory and skip LLM-based
157	  // content correction, returning the original proposed content on success.
158	  if (config.isPlanMode()) {
159	    return { originalContent, correctedContent: proposedContent, fileExists };
160	  }
161	
162	  const aggressiveUnescape = !isGemini3Model(config.getActiveModel());
163	
164	  correctedContent = await ensureCorrectFileContent(
165	    proposedContent,
166	    config.getBaseLlmClient(),
167	    abortSignal,
168	    config.getDisableLLMCorrection(),
169	    aggressiveUnescape,
170	  );
171	
172	  return { originalContent, correctedContent, fileExists };
173	}
